#include <list>
#include <iostream>

int main() {
    std::list<int> l = {10, 20, 30};
    auto it_20 = ++l.begin(); // Iterator pointing to 20

    // Insert 15. O(1).
    l.insert(it_20, 15);

    // it_20 remains valid and still points to 20 (or the node after 15).
    // This is safe, unlike vector/deque insertion.
    std::cout << *it_20 << std::endl; // Output: 20

    // Erase 10. O(1).
    l.erase(l.begin());
    // it_20 is still valid.
    std::cout << *it_20 << std::endl; // Output: 20
}
